import java.util.Scanner;

public class StockPortfolio {
    private String stockSymbol;
    private int quantity;
    private double buyPrice;
    private double currPrice;
    private double pnl;

    public StockPortfolio() {
        stockSymbol = "";
        quantity = 0;
        buyPrice = 0.0;
        currPrice = 0.0;
        pnl = 0.0;
    }

    public void input() {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter Stock Symbol: ");
        stockSymbol = in.nextLine().toUpperCase();
        System.out.print("Enter Shares Quantity: ");
        quantity = in.nextInt();
        System.out.print("Enter Purchase Price (Rs): ");
        buyPrice = in.nextDouble();
        System.out.print("Enter Current Market Price (Rs): ");
        currPrice = in.nextDouble();
    }

    public void calculateProfitLoss() {
        pnl = (currPrice - buyPrice) * quantity;
    }

    public void displayReport() {
        double investment = buyPrice * quantity;
        double returnPct = (pnl / investment) * 100.0;

        System.out.println("\n============== PORTFOLIO STATEMENT ==============");
        System.out.println("Stock Ticker     : " + stockSymbol);
        System.out.println("Shares Held      : " + quantity);
        System.out.println("Total Investment : Rs. " + investment);
        System.out.println("Current Value    : Rs. " + (currPrice * quantity));
        System.out.printf("Net Gain / Loss  : Rs. %.2f (%.2f%%)\n", pnl, returnPct);
        System.out.println("Status           : " + (pnl >= 0 ? "PROFIT" : "LOSS"));
        System.out.println("==================================================");
    }

    public static void main(String[] args) {
        StockPortfolio holding = new StockPortfolio();
        holding.input();
        holding.calculateProfitLoss();
        holding.displayReport();
    }
}
```

