import java.util.Scanner;

public class SortedArrayDeduplication {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        final int N = 15;
        int[] arr = new int[N];

        System.out.println("Enter " + N + " sorted integers (with duplicates):");
        for (int i = 0; i < N; i++) arr[i] = sc.nextInt();

        int[] unique = new int[N];
        int uCount = 0;

        for (int i = 0; i < N; i++) {
            if (i == 0 || arr[i] != arr[i - 1]) {
                unique[uCount++] = arr[i];
            }
        }

        System.out.print("\nUnique Elements: ");
        for (int i = 0; i < uCount; i++) System.out.print(unique[i] + " ");
        System.out.println("\nTotal Unique Count = " + uCount);
    }
}
