import java.util.Scanner;

public class AbundantNumberCheck {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter a positive integer: ");
        int n = sc.nextInt();

        if (n <= 0) {
            System.out.println("Please enter a positive integer.");
            return;
        }

        int divSum = 0;
        for (int i = 1; i <= n / 2; i++) {
            if (n % i == 0) divSum += i;
        }

        System.out.println("Sum of proper divisors = " + divSum);
        if (divSum > n) {
            System.out.println(n + " is an ABUNDANT NUMBER (Sum " + divSum + " > " + n + ").");
        } else if (divSum < n) {
            System.out.println(n + " is a DEFICIENT NUMBER (Sum " + divSum + " < " + n + ").");
        } else {
            System.out.println(n + " is a PERFECT NUMBER (Sum " + divSum + " == " + n + ").");
        }
    }
}
```

