import java.util.Scanner;

public class SpiralMatrixTraversal {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        final int R = 4, C = 4;
        int[][] mat = new int[R][C];

        System.out.println("Enter elements for 4x4 matrix:");
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) mat[i][j] = in.nextInt();
        }

        System.out.print("\nSpiral Order Traversal: ");
        int top = 0, bottom = R - 1, left = 0, right = C - 1;

        while (top <= bottom && left <= right) {
            for (int j = left; j <= right; j++) System.out.print(mat[top][j] + " ");
            top++;

            for (int i = top; i <= bottom; i++) System.out.print(mat[i][right] + " ");
            right--;

            if (top <= bottom) {
                for (int j = right; j >= left; j--) System.out.print(mat[bottom][j] + " ");
                bottom--;
            }

            if (left <= right) {
                for (int i = bottom; i >= top; i--) System.out.print(mat[i][left] + " ");
                left++;
            }
        }
        System.out.println();
    }
}
```

