import java.util.Scanner;

public class MenuDiamondFactors {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.println("========== UTILITY MENU ==========");
        System.out.println("1. Diamond Star Pattern");
        System.out.println("2. Prime Factorization");
        System.out.print("Enter choice (1 or 2): ");
        int choice = sc.nextInt();

        switch (choice) {
            case 1:
                System.out.print("Enter half-height n (e.g. 4): ");
                int n = sc.nextInt();
                for (int i = 1; i <= n; i++) {
                    for (int s = 1; s <= n - i; s++) System.out.print(" ");
                    for (int j = 1; j <= 2 * i - 1; j++) System.out.print("*");
                    System.out.println();
                }
                for (int i = n - 1; i >= 1; i--) {
                    for (int s = 1; s <= n - i; s++) System.out.print(" ");
                    for (int j = 1; j <= 2 * i - 1; j++) System.out.print("*");
                    System.out.println();
                }
                break;

            case 2:
                System.out.print("Enter positive number: ");
                int num = sc.nextInt();
                System.out.print("Prime factors of " + num + ": ");
                for (int d = 2; d * d <= num; d++) {
                    while (num % d == 0) {
                        System.out.print(d + " ");
                        num /= d;
                    }
                }
                if (num > 1) System.out.print(num);
                System.out.println();
                break;

            default:
                System.out.println("Invalid Choice.");
        }
    }
}
```

